api.look('paper');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1.2);
api.rect(cx-150, cy-190, 300, 380, {r:18, c:'fg', w:5, k});
api.line(cx, cy-190, cx, cy+190, {c:'fg', w:3, k:api.seg(t,0.3,1.4)});
api.line(cx-150, cy, cx+150, cy, {c:'fg', w:3, k:api.seg(t,0.5,1.6)});
for (let i = 0; i < 14; i++) {
  const x = cx-130 + api.rand(i)*260;
  const y = ((t*140 + api.rand(i+50)*380) % 360) - 170 + cy;
  api.line(x, y, x-3, y+16, {c:'a2', w:2.5, a:0.8*api.seg(t,0.8,1.6)});
}
api.say('Sunday morning. Rain.', 0.4, 3.6);

api.look('paper');
const cx = api.w/2, cy = 330;
api.cam(0, 0, api.lerp(1, 1.12, api.ease(api.seg(t,0,6))), 0);
api.rect(cx-150, cy-190, 300, 380, {r:18, c:'fg', w:5});
api.line(cx, cy-190, cx, cy+190, {c:'fg', w:3});
api.line(cx-150, cy, cx+150, cy, {c:'fg', w:3});
api.glow(cx, cy, 220, {c:'a2', a:0.15});
for (let i = 0; i < 40; i++) {
  const x = cx-140 + api.rand(i)*280;
  const sp = 90 + api.rand(i+9)*120;
  const y = ((t*sp + api.rand(i+50)*400) % 380) - 185 + cy;
  api.line(x, y, x-3, y+14, {c:'a2', w:2, a:0.75});
}
// droplets sliding down glass
for (let i = 0; i < 5; i++) {
  const x = cx-110 + i*55 + api.rand(i+20)*10;
  const y = cy-170 + ((t*30*(0.6+api.rand(i)) + api.rand(i+30)*300) % 340);
  api.drop ? 0 : 0;
  api.shape('drop', x, y, 22, {c:'a2', fill:'a2', a:0.7});
}
api.say('Rain taps the window.', 0.4, 5.5);

api.look('paper');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 1.8);
api.path('M-90 -50 L-75 70 C-70 110 70 110 75 70 L90 -50 Z', {x:cx, y:cy, s:1.5, c:'fg', w:4, fill:'accent', k});
api.path('M88 -30 C150 -40 150 50 78 40', {x:cx, y:cy, s:1.5, c:'fg', w:4, k:api.seg(t,1,2.4)});
api.ellipse(cx, cy-75, 135, 22, {c:'fg', w:4, fill:'#5a3a24', k:api.seg(t,0.6,1.6)});
api.ellipse(cx, cy+190, 200, 22, {c:'fg', w:3, a:0.5, k:api.seg(t,0.3,1.4)});
const sk = api.seg(t, 2, 3);
for (let s = 0; s < 3; s++) {
  const pts = [];
  for (let j = 0; j < 12; j++) {
    const yy = cy-110 - j*16 - ((t*20 + s*30) % 30)*0;
    pts.push([cx-40 + s*40 + Math.sin(t*1.6 + j*0.5 + s)*10, yy]);
  }
  api.poly(pts, {c:'dim', w:4, a:0.6*sk});
}
api.glow(cx, cy, 200, {c:'warn', a:0.25*sk});
api.say('A warm cup of coffee.', 0.5, 5.5);

api.look('paper');
const cx = api.w/2, cy = 380;
const z = api.lerp(1, 0.75, api.ease(api.seg(t,0,3)));
api.cam(0, 40, z, api.lerp(0, -0.03, api.ease(api.seg(t,0,5))));
api.rect(cx-150, cy-420, 300, 300, {r:18, c:'fg', w:4, a:0.7});
api.line(cx, cy-420, cx, cy-120, {c:'fg', w:3, a:0.7});
api.line(cx-150, cy-270, cx+150, cy-270, {c:'fg', w:3, a:0.7});
for (let i = 0; i < 25; i++) {
  const x = cx-140 + api.rand(i)*280;
  const y = ((t*110 + api.rand(i+50)*300) % 290) - 410 + cy;
  api.line(x, y, x-3, y+14, {c:'a2', w:2, a:0.7});
}
api.path('M-90 -50 L-75 70 C-70 110 70 110 75 70 L90 -50 Z', {x:cx, y:cy, s:1.2, c:'fg', w:4, fill:'accent'});
api.path('M88 -30 C150 -40 150 50 78 40', {x:cx, y:cy, s:1.2, c:'fg', w:4});
api.ellipse(cx, cy-60, 108, 18, {c:'fg', w:4, fill:'#5a3a24'});
for (let s = 0; s < 3; s++) {
  const pts = [];
  for (let j = 0; j < 10; j++) pts.push([cx-30+s*30+Math.sin(t*1.6+j*0.5+s)*8, cy-90-j*14]);
  api.poly(pts, {c:'dim', w:3, a:0.6});
}
api.say('Nowhere to be.', 0.5, 4.5);

api.look('paper');
const cx = api.w/2, cy = 330;
api.glow(cx, cy, 300, {c:'warn', a:0.2*api.seg(t,0,2)});
api.kinetic('Slow down.', cx, cy, {mode:'rise', k:api.seg(t,0.3,2.2), size:44, t});
api.shape('heart', cx, cy+90, 70, {c:'accent', fill:'accent', k:api.seg(t,1.5,3)});
api.swarm(30, t, {mode:'rise', cx, cy:cy+300, rx:150, ry:200, c:'a2', size:3});
api.say('Just this morning.', 0.5, 4.5);
